"""Final customer guide, including installation, compatibility and product facts.

Run the PDF skill's operation marker before authoring; render every page after.
"""
from pathlib import Path
import json
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,PageBreak,KeepTogether
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib.colors import HexColor
ROOT=Path(__file__).resolve().parents[2]
out=ROOT/'output/pdf';out.mkdir(parents=True,exist_ok=True)
styles=getSampleStyleSheet()
styles['BodyText'].fontName='Helvetica';styles['BodyText'].fontSize=10.5;styles['BodyText'].leading=15;styles['BodyText'].spaceAfter=9
styles['Heading1'].fontName='Helvetica-Bold';styles['Heading1'].fontSize=25;styles['Heading1'].leading=31;styles['Heading1'].spaceAfter=13;styles['Heading1'].textColor=HexColor('#183932')
styles['Heading2'].fontName='Helvetica-Bold';styles['Heading2'].fontSize=12;styles['Heading2'].leading=17;styles['Heading2'].spaceBefore=10;styles['Heading2'].spaceAfter=5
styles.add(ParagraphStyle(name='Intro',fontName='Helvetica',fontSize=12,leading=18,textColor=HexColor('#58625f'),spaceAfter=15))
styles.add(ParagraphStyle(name='SmallNote',fontName='Helvetica',fontSize=9,leading=12,textColor=HexColor('#58625f'),spaceAfter=9))
story=[]
def text(body,style='BodyText'):story.append(Paragraph(body,styles[style]))
def page(title,intro):
 if story:story.append(PageBreak())
 text(title,'Heading1');text(intro,'Intro')
def step(title,body):story.append(KeepTogether([Paragraph(title,styles['Heading2']),Paragraph(body,styles['BodyText'])]))
def footer(c,doc):
 c.setStrokeColor(HexColor('#d6dfdb'));c.line(44,47,551,47);c.setFont('Helvetica',8);c.setFillColor(HexColor('#58625f'));c.drawString(44,32,'STENCIL STUDIO  |  OFFLINE BROWSER EDITION  |  M8');c.drawRightString(551,32,str(doc.page))

page('Start on Windows','Download once. Create locally in your browser.')
text('Stencil Studio is an offline browser application. Double-clicking its graphical launcher opens the editor in your installed browser. No account, subscription, development tools or separate server installation is needed.')
step('1. Extract the complete download','Use <b>StencilStudio-Windows-x64.zip</b>. In File Explorer, right-click the ZIP and choose <b>Extract All</b>. Open the extracted folder. Keep <b>Stencil Studio.exe</b> beside the complete <b>Studio Support</b> folder. Do not run it from inside the ZIP.')
step('2. Open the launcher','Double-click <b>Stencil Studio.exe</b>. The default browser opens an address beginning with <b>http://localhost:</b>. This address is on your own computer. Keep the small launcher window open. Chrome is recommended; Edge is supported on the tested Windows configuration.')
step('3. Understand a publisher warning','The Windows executables are unsigned. Windows may show <b>Windows protected your PC</b> or an unknown-publisher warning. Confirm that you deliberately obtained this exact package from your trusted seller and that its checksum matches. If offered, <b>More info &gt; Run anyway</b> approves that app. A checksum detects changed bytes; it does not identify the publisher or certify malware safety.')
step('If Windows will not allow it','Smart App Control, company policy or security software can block unsigned software without an app-specific override. Stop and contact the seller or your administrator. Do not turn off SmartScreen, Smart App Control, antivirus or other system-wide protections. Do not override a malware or tampering alert.')
step('4. Save and quit','Use <b>Save Project</b> and download your exports before closing. <b>Quit Studio</b> in the launcher stops its local server and browser processing. Closing every Studio tab also stops it after a short delay. Other browser windows remain yours.')
text('First-download approval differs from a successful local launch. See page 5 for test limits and <link href="https://learn.microsoft.com/en-us/windows/apps/package-and-deploy/smartscreen-reputation" color="#22594b">Microsoft\'s SmartScreen and Smart App Control guidance</link> for current policy behavior.','SmallNote')

page('Start on Mac','Choose the package for your Mac, then keep its app intact.')
step('1. Choose Apple Silicon or Intel','Open <b>Apple menu &gt; About This Mac</b>. For an Apple M-series chip, use <b>StencilStudio-macOS-Apple-Silicon.zip</b>. For an Intel processor, use <b>StencilStudio-macOS-Intel.zip</b>. The separate downloads each contain their matching launcher and editor resources.')
step('2. Extract and open','Double-click the ZIP to extract it. Open <b>Stencil Studio.app</b>. Keep the entire app bundle intact. You can keep it in a normal user folder or move the complete app to your own Applications folder. Your default browser opens the local editor; keep the launcher window open.')
step('3. If Apple blocks an unidentified developer','These bundles have ad hoc integrity signatures, without Apple Developer ID signing or notarization. Try opening the app first. If you trust its source and have checked the package, open <b>System Settings &gt; Privacy &amp; Security</b>, scroll to its blocked-app message and choose <b>Open Anyway</b> if offered. Confirm the app-specific <b>Open</b> or second <b>Open Anyway</b> button. macOS can require an administrator username and password for this approval. Apple describes the procedure at <link href="https://support.apple.com/en-us/102445" color="#22594b">support.apple.com/en-us/102445</link>.')
step('When to stop','An unidentified-developer warning differs from an alert that software is damaged or will harm your computer. For damage, failed checksums, malware alerts or an unavailable approval option, stop and contact the seller or administrator. Do not remove quarantine in Terminal, disable Gatekeeper, reduce startup security or change global protection settings.')
step('4. Browser and offline use','Chrome is recommended. The tested Apple Silicon Safari configuration supports 3D. The updated Intel package uses real software 3D when Safari cannot provide a healthy WebGL context; large meshes can respond more slowly. If necessary, copy the local address from the launcher into Chrome. Downloading and installing a browser need internet. Artwork processing, saved projects and exports run locally afterward.')
text('This is a launcher for a browser editor. It does not install a native editor, Electron, Tauri or a WebView runtime. Exact tested versions and security-test limits are on page 5.','SmallNote')

page('Make your first stencil','Upload, generate, customize, inspect and export.')
step('1. Choose artwork','Select <b>Choose Image</b> or drop a PNG, JPG, BMP or SVG file onto the empty workspace. Start with a clear, high-contrast image. <b>Create from Text</b> is available for text artwork. Your original artwork stays in the project.')
step('2. Generate','Choose a <b>Stencil style</b>, then select <b>Make Stencil</b>. Wait for full-quality generation. The readiness panel and available export link show when the result is current. Detailed photographs and large models take longer than simple logos.')
step('3. Customize','Use Quick Adjustments for stencil width, base thickness, bridge width and artwork settings. Width and thickness use millimetres. Live edits may show a draft before full quality completes. Wait for the current export to become available. Imported specialist workflows may require <b>Make Stencil</b> after changes.')
step('4. Inspect','Use the stencil view and <b>3D</b> tab. Orbit the model and check thin features, isolated areas and bridges. Height cutaways and visibility controls help inspection; they do not alter the printable export. Geometry checks identify common defects but cannot guarantee that a physical print will succeed.')
step('5. Export and save','Select <b>Export STL</b> for a single model or <b>Export ZIP</b> for a workflow with multiple parts. Keep the complete ZIP contents. Use <b>Save Project</b> to download the project JSON containing artwork and settings. Keep it outside the application folder. Reopen the launcher later and choose <b>Open Project</b>.')
step('Your project backup','The automatic draft belongs to the browser, its profile and Studio address. Private browsing, deleted site data, full storage or another browser can prevent recovery. There is one shared automatic draft slot per origin; two tabs can hold separate live projects but can overwrite that slot. Save each project to its own file before quitting.')

page('Manufacturing workflows','Advanced tools are available through All Settings.')
step('Colours and layers','Open <b>All Settings &gt; Colours and layers</b> for multi-colour work. Keep plate dimensions and registration consistent between passes. Preview each plate and its bridges. Visibility controls aid inspection; choose actual export contents explicitly in Export options. Preserve registration parts with the exported set.')
step('Tiles and large stencils','Use <b>Tiles and large stencils</b> to split a model into printable sections. Enter the printer\'s usable width and height, allowing for its own margins. Review seam and connector positions. Planning sections before construction and splitting a finished stencil are distinct methods with their own controls.')
step('Mounting, connectors and hardware','Use <b>Mounting and borders</b> and <b>Screws, connectors and hardware</b> for the required assembly. Check plate thickness, mating parts, thread sizes, clearances and the export selection. Print a small fitting sample before a complete assembly. Printer/material tolerances determine actual fit.')
step('Export the complete assembly','Open <b>Export options</b> and review the manufacturing contents. Retain every required printable part and included assembly/layout record. Settings changes can invalidate an earlier export; generate again before downloading. A valid mesh is a file-quality check, not a load rating or a printer calibration certificate.')
step('Batch processing','Use <b>Batch processing and diagnostics</b> for local saved-project variations. Review ranges, units and output settings before running. Keep Studio open until the collection is complete and downloaded. A batch does not keep running after quitting. Inspect the included summary and representative models before printing the whole collection.')
text('A slicer, suitable 3D printer, material and calibration are separate requirements for physical production. They are not included in this download. Validate strength, wall thickness, bed adhesion, supports and moving/fastening fits for your application.','SmallNote')

page('Compatibility & help','Qualified configurations, practical limits and recovery steps.')
step('Measured systems and browsers','Windows: Windows 11 Home <b>10.0.26300</b>; additional hosted tests on Windows Server 2025. Chrome and Edge passed packaged workflows. Apple Silicon: <b>macOS 26.6.2</b>, Safari 26.6.2 and measured Chrome/Firefox builds. Intel: <b>macOS 15.7.9</b>, Safari 26.6 with software 3D and measured Chrome/Firefox builds. Mac results came from genuine OS runners, not physical retail Mac qualification. Read <b>Platform Test Record.txt</b> inside each ZIP for exact historical browser builds.')
step('Limits to compatibility claims','Windows 10, older macOS versions and physical Macs beyond CI remain unverified. The Mac build target of 13.3 is not certification of every version from 13.3 onward. Windows Firefox 3D remains unqualified on its tested graphics environment. Use Chrome, or Edge on Windows. Browser versions outside measured configurations are not blanket-certified.')
security=ROOT/'docs/m8/evidence/security-summary.json'
summary=json.loads(security.read_text()) if security.exists() else None
security_text=summary['customer_guide_summary'] if summary else 'Customer first-download approval remains unverified. Unquarantined launches and command-line assessments alone do not prove that an ordinary customer can complete a security-warning walkthrough.'
step('First-download test status',security_text)
step('If the editor or a model will not appear','Use the launcher rather than opening index.html. Check complete extraction, correct architecture and an installed browser with WebAssembly, workers, downloads and storage enabled. Try the local address in Chrome. Keep current browser/GPU drivers. The Intel package can fall back to software 3D; the unchanged Windows and Apple Silicon builds retain their measured graphics requirements.')
step('Busy address, updates and removal','If the saved Studio address is busy, the launcher offers a temporary session. Open a saved project there, or free the original address to return to its browser draft. To update, save, quit and extract a complete new folder/app without mixing support files. Removing the app/folder leaves separately saved projects and exports intact. Browser drafts and launcher settings are separate.')
text('Windows settings: %LOCALAPPDATA%\\Stencil Studio\\Stencil Studio\\data<br/>Mac settings: ~/Library/Application Support/com.Stencil-Studio.Stencil-Studio<br/>For support, provide the platform, browser version, exact message and a non-sensitive sample project. No account credentials or private artwork are needed to describe an installation problem.','SmallNote')

page('Product information','Factual listing copy and purchase requirements.')
step('What this digital product contains','Offline browser-based Stencil Studio for Windows x64, Mac Apple Silicon and Mac Intel. The five-file set contains three platform ZIPs, this Quick Start PDF and a Read Me/checksum text file. Choose the correct ZIP for your computer. No physical stencil, printed part, slicer, printer, browser installer or material is included.')
step('What it does','Create stencils from images or text; adjust artwork, dimensions, bridges and geometry; inspect 3D; and prepare multi-colour plates, tiles, mounting parts, connectors and local batch variations. Export STL or manufacturing ZIP output as the selected workflow permits. Save portable project JSON files to continue work later.')
step('How it runs','Customers double-click a small graphical launcher. The complete editor opens in an installed browser and is served only on the local computer. Artwork processing uses bundled engines locally. There is no cloud processing, account, subscription or recurring licence-service check. The initial download, browser setup and operating-system security checks can need internet; browser/OS background services are outside this app\'s control.')
step('Required before purchase','A compatible computer and browser from the measured configurations on page 5; permission to run unsigned/ad hoc signed software using app-specific OS approval where available; local storage for projects and exports; and a separate slicer/printer/material for physical printing. Managed devices or Smart App Control may prevent launch. Do not promise compatibility with all Windows/Mac versions or every browser.')
step('Honest limitations','The software generates files, not guaranteed print outcomes. Thin features, strength, hardware fit and printer tolerances require review and calibration. Large projects take more time and memory; software 3D can be slower. Saved projects should be backed up independently. Font and other third-party licences are supplied inside the packages; use artwork you are entitled to reproduce.')
text('Prepared for customer review. This document does not announce a published Etsy listing, guarantee warning-free installation or promise physical testing that has not occurred. Final selling, pricing, support and refund terms belong to the seller.','SmallNote')
SimpleDocTemplate(str(out/'StencilStudio-Quick-Start.pdf'),pagesize=(595.28,841.89),rightMargin=44,leftMargin=44,topMargin=45,bottomMargin=65,title='Stencil Studio - Customer Quick Start and Product Information',author='Stencil Studio',pageCompression=1,invariant=1).build(story,onFirstPage=footer,onLaterPages=footer)
print(out/'StencilStudio-Quick-Start.pdf')
